// CARD-0338: early-warning probe for the environmental Google Sheet.
// One node, two kinds of input: a tick (from the inject node -- start a probe) and a
// response (msg._health, from the HTTP request node -- evaluate it).
// Outputs: [0] the probe request, [1] a log line, [2] a push to the Pixel.
//
// Why a probe of its own: on 2026-09-25 the Sheet stopped accepting writes at ~10:07 MST
// and the only signal was the write queue's alert, throttled to one per 30 minutes.
// action=version never touches the spreadsheet, so it stayed fast the whole time;
// action=health opens the spreadsheet and reads a real cell.
//
// One probe in flight at a time, 30 s request timeout, 45 s hard stop -- a hung probe must
// never pile up against a backend that is already struggling.
var st = context.get('st');
if (!st) { st = { inFlight: false, seq: 0, startedAt: 0, timer: null, bad: false, badSince: 0, lastAlert: 0, strikes: 0, firstStrikeAt: 0 }; context.set('st', st); }
var SLOW_MS = 10000;
var REALERT_MS = 30 * 60 * 1000;
var HARD_STOP_MS = 45000;
var STRIKES_TO_ALERT = 2;

function stripUrls(s) { return String(s).replace(/https?:\/\/\S+/g, '<url>').replace(/\s+/g, ' ').slice(0, 100); }
function fmtMin(ms) { var m = Math.round(ms / 60000); return m + ' min'; }

function notify(text, category) {
    var logMsg = { payload: JSON.stringify({ component: 'sheet-health', category: category, message: text }) };
    var HA_TOKEN = env.get('HA_TOKEN') || flow.get('haToken') || global.get('haToken');
    var pushMsg = {
        url: 'http://localhost:8123/api/services/notify/mobile_app_pixel_10_pro_xl',
        method: 'POST',
        headers: { 'Authorization': 'Bearer ' + HA_TOKEN, 'Content-Type': 'application/json' },
        payload: JSON.stringify({ message: text, title: 'JCTsh Sheet health' })
    };
    return [null, logMsg, pushMsg];
}

function handle(ok, ms, detail) {
    var now = Date.now();
    var bad = !ok || ms > SLOW_MS;
    var why = !ok ? detail : ('health call slow (' + Math.round(ms / 1000) + ' s)');
    // Google's front end throws the occasional transient 404/blip (seen repeatedly on
    // 2026-09-25, including as the very first sign of the outage), so one bad check is
    // only a strike -- alert on two in a row (at most ~10 minutes to notice a real outage).
    if (!bad) { st.strikes = 0; st.firstStrikeAt = 0; }
    else { if (!st.strikes) st.firstStrikeAt = now; st.strikes += 1; }
    if (bad && !st.bad && st.strikes < STRIKES_TO_ALERT) return null;
    if (bad && !st.bad) {
        st.bad = true; st.badSince = st.firstStrikeAt; st.lastAlert = now;
        return notify('Sheet health: ' + why + ' -- the environmental Sheet is failing or slow; readings are being held by the write queue.', 'Alert');
    }
    if (bad && st.bad) {
        if (now - st.lastAlert > REALERT_MS) {
            st.lastAlert = now;
            return notify('Sheet health: still bad after ' + fmtMin(now - st.badSince) + ' (' + why + ').', 'Alert');
        }
        return null;
    }
    if (!bad && st.bad) {
        var mins = fmtMin(now - st.badSince);
        st.bad = false; st.badSince = 0; st.lastAlert = 0;
        return notify('Sheet health: recovered after ' + mins + ' (health call took ' + (ms / 1000).toFixed(1) + ' s).', 'System');
    }
    return null;
}

// Test hook (the "TEST" inject node): force the next N probes to count as failed, so the
// whole alert -> push -> recovery path can be exercised on demand without breaking anything.
if (msg._forceBad) { flow.set('healthForceBad', msg._forceBad); return null; }

if (!msg._health) {
    if (st.inFlight && Date.now() - st.startedAt < HARD_STOP_MS + 5000) return null;
    st.inFlight = true;
    st.startedAt = Date.now();
    st.seq += 1;
    var seq = st.seq;
    clearTimeout(st.timer);
    st.timer = setTimeout(function () {
        if (st.inFlight && st.seq === seq) {
            st.inFlight = false;
            var out = handle(false, HARD_STOP_MS, 'no response within ' + (HARD_STOP_MS / 1000) + ' s');
            if (out) node.send(out);
        }
    }, HARD_STOP_MS);
    var url = env.get('APPS_SCRIPT_URL') + '?key=' + encodeURIComponent(env.get('APPS_SCRIPT_KEY')) + '&action=health';
    return [{ _health: true, _seq: seq, url: url, method: 'GET', requestTimeout: 30000 }, null, null];
}

if (!st.inFlight || msg._seq !== st.seq) return null;
st.inFlight = false;
clearTimeout(st.timer);
var ms = Date.now() - st.startedAt;
var body = null;
try { body = JSON.parse(msg.payload); } catch (e) {}
var ok = msg.statusCode === 200 && body && body.status === 'ok';
var detail = ok ? '' : ('HTTP ' + msg.statusCode + ': ' + stripUrls(body && body.message ? body.message : msg.payload));
var forced = flow.get('healthForceBad') || 0;
if (forced > 0) { flow.set('healthForceBad', forced - 1); ok = false; detail = 'forced test failure'; }
return handle(ok, ms, detail);

// A failed push must not vanish silently.
if (msg.statusCode !== 200 && msg.statusCode !== 201) {
    return { payload: JSON.stringify({ component: 'sheet-health', category: 'Alert',
        message: 'HA push for a Sheet-health alert failed (HTTP ' + msg.statusCode + ') -- the Pixel may not have been notified.' }) };
}
return null;
